code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    rb = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds)-1)]
    cb = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds)-1)]
    nr, nc = len(rb), len(cb)
    cells = [[set() for _ in range(nc)] for _ in range(nr)]
    positions = {2: [], 3: []}
    for r in range(h):
        for c in range(w):
            if grid[r][c] in positions:
                br = next(i for i,(a,b) in enumerate(rb) if a <= r < b)
                bc = next(i for i,(a,b) in enumerate(cb) if a <= c < b)
                positions[grid[r][c]].append((br,bc))
    for color, pts in positions.items():
        if len(pts) >= 2:
            (r1,c1),(r2,c2) = pts[:2]
            if r1 == r2:
                for c in range(min(c1,c2), max(c1,c2)+1): cells[r1][c].add(color)
            elif c1 == c2:
                for r in range(min(r1,r2), max(r1,r2)+1): cells[r][c1].add(color)
    out = [row[:] for row in grid]
    for br,(r0,r1) in enumerate(rb):
        for bc,(c0,c1) in enumerate(cb):
            colors = cells[br][bc]
            if colors:
                value = 6 if len(colors) > 1 else next(iter(colors))
                for r in range(r0,r1):
                    for c in range(c0,c1): out[r][c] = value
    return out
'''
