def make_grid(n, size, markers):
    dim=n*size+n-1
    g=[[0]*dim for _ in range(dim)]
    for k in range(n-1):
        rr=(k+1)*size+k
        cc=(k+1)*size+k
        for j in range(dim): g[rr][j]=8; g[j][cc]=8
    for color, br, bc, lr, lc in markers:
        g[br*(size+1)+lr][bc*(size+1)+lc]=color
    return g

